/**
 * 渲染中如果有其他组件，从主页面获取模块组件信息
 */
globals.m = (uid) => {
    if(globals.state.mModules[uid]) return globals.state.mModules[uid];
    // if(moduleStore){
    //     console.log('moduleStore.elements', uid, moduleStore.elements.has(uid))
    // }
    if(moduleStore && moduleStore.elements.has(uid)){
        const element = moduleStore.elements.get(uid);
        // console.log('element', element)
        if(element.jsxRender){
            // globals.state.mModules[uid] = dynamicCreateModule(element.jsxRender)
            // 改为实时预览
            return dynamicCreateModule(element.jsxRender);
        }
    }
    return globals.state.mModules[uid] || (() => <span>Null：{uid}</span>);
}

/**
 * 更换其他文件
 */

globals.h = ((...args: [any, any]) => {
    let [name, props, ...children] = args;
    switch(name){
        case 'img':
        case 'image':
            if(fileStore.imgMap[props.src]){
                props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
            }
        break;
        case Image:
            if(fileStore.imgMap[props.src]){
                props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
            }
        break;
        case Image.Preview:
            if(fileStore.imgMap[props.src]){
                props = { ...props, src: fileStore.imgMap[props.src], alt: props.src }
            }
        break;
        case Image.PreviewGroup:
            if(props.srcList && Array.isArray(props.srcList) && props.srcList.length){
                props = {
                    ...props,
                    srcList: props.srcList.map((url) => {
                        if(fileStore.imgMap[url]) return fileStore.imgMap[url];
                        return url;
                    })
                }
            }
        break;
    }
    return React.createElement(name, props, ...children)
}) as any


// 这是预览页面（预览H5页面）

const MobilePage = () => {

    const [text, setText] = useState('');
    const [moduleKey, setModuleKey] = useState('');
    const [modulePropos, setModuleProps] = useState({});


    useEffect(() => {
        // 准备好了， 发送通知
        const handleMessage = (event) => {
            if(typeof event.data == "object"){
                const { key, data } = event.data;
                setModuleKey(Date.now().toString(32));
                switch(key){
                    case MobileKey.Template:
                        // 替换 URL 中的路径
                        let result = data.replace(/url\(['"]?(.*?)['"]?\)/g, (match, p1) => {
                            // 根据不同环境替换路径
                            let updatedUrl = p1;
                            if(fileStore.imgMap[updatedUrl]){
                                updatedUrl = fileStore.imgMap[updatedUrl];
                            }
                            return `url('${updatedUrl}')`;
                        });
                        // 发送配置信息
                        setText(result);
                    break;
                    case MobileKey.TemplateProps:
                        setModuleProps(JSON.parse(data));
                    break;
                }
            }
        };
    
        window.addEventListener('message', handleMessage);
        window.parent.postMessage({
            key: MobileKey.ready,
        }); // 替换为父窗口的 URL
        return () => {
            window.removeEventListener('message', handleMessage);
        };
    },[])


    return useObserver(() => {

        const [isReady, setIsReady] = useState(false);

        useEffect(() => {
            (async() => {
                // 重新加载完整多语言
                await locales.changeLang(locales.lang);
                setIsReady(true);
            })()
        },[])

        const PageElement = useMemo(() => {
            if(isReady && text){
                console.log('PageElement', text)
                // tailwindcss.toCss(text).then((res) => {
                //     console.log('PageElement-tailwindcss', res)
                // })
                return dynamicCreateModule(text);
            }
            return (props) => <span></span>;
        },[text, isReady])


        if(!isReady) return null;

        return <PageElement key={moduleKey} {...modulePropos} />
    })
}



export const initIframe = () => {
    language.setStore(win.language.getStore());
    mainRoutes.push({
        path: "*",
        key: "/",
        component: MobilePage,
    })

    // 当前是iframePage 类型
    ReactDOM.render(<App />, document.getElementById('root'));
}