import { returnToLogin } from "@/utils";
import ajax from "@/utils/ajax";
import store from '@/store';
import { action, computed, observable, makeObservable, toJS } from "mobx";
import app from "./app";
import _ from 'lodash';
import mainConfig from 'mainConfig';
import user from "@code/store/user";

const tokenKey = mainConfig.TokenKey;

interface UserData {
  tenant?: string;
  id?: string;
  roles?: string[];
  permissions: Record<string, string[]>;
  token?: string;
}

const permissionAll = new Proxy({}, { get(target, prop) { return ['*'] }});

/**
 * 存储用户信息
 */
class UserStore {
  @observable userToken = this.getToken();

  // 是否使用构建数据
  @observable publishReady = false;


  @observable isLoaging = false;

  @observable user: UserData = {
    permissions: {}
  };

  @observable userLoading = false;

  // devToken 优先级比用户token 要高，针对次级开发token
  devToken = "";


  getStore = () => {
    return {
      ..._.pick(this,['userToken', 'publishReady', 'isLoaging', 'userLoading', 'devToken']),
      user: toJS(this.user),      
    }
  }

  @action setStore = (data: ReturnType<typeof this.getStore>) => {
    Object.assign(this, data);
  }

  @action
  setUserToken = (token) => {
    this.userToken = token;
    this.setToken(token);
  }
  @action
  clearUserToken = () => {
    this.userToken = "";
  }


  @action
  setUserInfo = (user: UserData) => {
    this.user = { permissions: {}, ...user };
    app.userId = user.id;
    app.tenantId = user.tenant;
    this.setUserToken(user.token);
    this.setUserLoading(true);
  }


  @action setUserLoading = (bool) => {
    this.userLoading = bool;
  }


  constructor() {
    makeObservable(this);
  }


  // 用户权限点
  @computed get permissions(){
    if(this.user.roles.includes('admin')){
      // 管理员拥有任何权限
      return permissionAll
    }
    return this.user.permissions;
  }

  setDevToken = (token) => {
    this.devToken = token;
    // dev 环境，写入开发账号
    ajax.post('/dev/UserLogin', {
        loginname: 'admin',
    }).then((res) => {
      if(res.data){
        user.setInfo(res.data);
      }
    }).catch(() => {
        
    })
  }

  get token(){
    return this.devToken || this.userToken;
  }










  // 获取token
  getToken(){
    const time = localStorage.getItem(`${tokenKey}-express`);
    const token = localStorage[tokenKey];
    if(token && time && Date.now().toString() < time){
      return token;
    }
    return;
  }

  // 获取token 过期时间
  /**
   * @title 更新用户token信息
   * @param value token
   */
  setToken(value: string, expressTime: number = 12){
    localStorage.setItem(tokenKey, value);
    const time = (expressTime * 3600 * 1000) + Date.now();
    localStorage.setItem(`${tokenKey}-express`, time.toString());
  }


  // 退出登陆
  logout(){
    localStorage.removeItem(tokenKey);
    location.reload();
  }
}

export default new UserStore();