import { Table, TableProps, Tag, Tooltip, Typography, Image, Space, Popover } from '@arco-design/web-react';
import React, { useMemo, useState } from 'react';
import _ from 'lodash';
import './style.less';
import TableFixed from './TableFixed';
import TableFixedMove from './TableFixedMove';
import { ProColumn, ProTableProps } from './interface';
import classNames from 'classnames';
import i18next from 'i18next';
import { IconInfoCircle } from '@arco-design/web-react/icon';

export default function ProTable({ tableMode = 'resizable', fixedLayout, ...props }: ProTableProps){

    const TableElement = useMemo(() => {
        if(tableMode == 'resizable') return TableFixed;
        else if(tableMode == 'move') return TableFixedMove;
        return Table;
    },[tableMode])

    const columns: TableProps['columns'] = useMemo(() => {
        return (props.columns || []).map((o) => {
            const { enum: enums, format, fieldProps, copyable, tooltip, addBefore, addAfter, ...item } = o;
            if(addBefore || addAfter){
                return {
                    render: (col) => `${addBefore || ''}${col}${addAfter || ''}`,
                    ...item,
                }
            }
            if(format){
                switch(format){
                    case "i18n":
                        return {
                            render: (col, rowData) => i18next.t(col, rowData),
                            ...item,
                        }
                    case 'text':
                        item.ellipsis = true;   // text 文本默认使用省略号展示
                    break;
                    case "tags":
                        return {
                            render: (col) => {
                                const { labelField="label" } = fieldProps || {}
                                if(Array.isArray(col)){
                                    return (
                                        <Space size="small" className="flex flex-wrap">
                                            {(col.slice(0,1)).map((o, i) => {
                                                return (
                                                    <Tag key={i} color='arcoblue'>{o[labelField]}</Tag>
                                                )
                                            })}
                                            {col.length > 1? (
                                                <Popover content={(
                                                    <Space size="small">
                                                        {col.map((o, i) => {
                                                            return (
                                                                <Tag key={i} color='arcoblue'>{o[labelField]}</Tag>
                                                            )
                                                        })}
                                                    </Space>
                                                )}>
                                                    <Tag key="sum" color='arcoblue'>
                                                        +{ col.length - 1 }
                                                    </Tag>
                                                </Popover>
                                            ): null}
                                        </Space>
                                    )
                                }
                                return null;
                            },
                            ...item
                        }
                    case "image":
                        return {
                            render: (col) => {
                                return (
                                    <Image src={col} height={30}/>
                                )
                            },
                            ...item
                        }
                    break;
                }
            }
            if(enums){
                const valueEnum = enums.reduce((obj, o) => {
                    if(typeof o === 'object'){
                      return _.assign(obj, { [o.value]: o });
                    }
                    return _.assign(obj, { [o]: { label: o } })
                }, {});
                return {
                    render: (col) => {
                        // undefined 为默认类型，当参数不匹配的时候会使用undefined作为默认参数
                        if(valueEnum[col]){
                            if('color' in valueEnum[col]){
                                return (
                                    <Tag color={valueEnum[col].color}>
                                        {valueEnum[col].label}
                                    </Tag>
                                )
                            }else {
                                return valueEnum[col].label
                            }
                        }
                        return col;
                    },
                    ...item
                }
            }else if(copyable){
                return {
                    render: (value) => {
                        if(value){
                            const element = (
                                <Typography.Paragraph
                                    ellipsis={item.ellipsis}
                                    className="pro-table-typography"
                                    copyable
                                >{value}</Typography.Paragraph>
                            )
                            if(item.ellipsis){
                                return (
                                    <Tooltip content={value}>
                                        {element}
                                    </Tooltip>
                                )
                            }
                            return element;
                        }
                        return value;
                    },
                    ...item
                }
            }
            if(typeof o.title === "string"){
                if(tooltip){
                    item.title = (
                        <div>
                            {item.title}
                            <Tooltip content={tooltip}>
                                <IconInfoCircle />
                            </Tooltip>
                        </div>
                    ) 
                }
            }
            return item;
        })
    },[props.columns])


    return (
        <TableElement
            rowKey="id"
            {...props}
            className={classNames(props.className, {
                'pro-table': true,
                'table-scroll-y-full': fixedLayout
            })}
            columns={columns}
        />
    )
}

ProTable.TableFixed = TableFixed;
ProTable.TableFixedMove = TableFixedMove;