import React from "react";
import FormItemRender from './components/FormItem';
import { Button, Form, Grid, Input, Space } from "@arco-design/web-react";
import { FormItem } from "../interface";
import { IconDelete, IconArrowRise, IconArrowFall } from "@arco-design/web-react/icon";



interface FormGenerateProps {
    colSpan?: number;
    notCol?: boolean;
    parentField?: string;
    formList: FormItem[]
}

const FormGenerate = ({
    colSpan = 24,
    notCol,
    parentField = "",
    formList
}: FormGenerateProps) => {

    const { form } = Form.useFormContext();

    const children = formList.map((o) => {

        const { list, show, children, formItemProps = {}, colProps = {} } = o;

        const field = parentField? `${parentField}.${o.field}` : o.field;

        if (show === false) {
            return null;
        }

        if (list) {
            const formListRender = (
                <Form.List field={field} noStyle >
                    {(fields, { add, remove, move }) => {
                        return (
                            <div>
                                {fields.map((item, index) => {
                                    return (
                                        <Grid.Row key={item.key}>
                                            <FormGenerate
                                                notCol={notCol}
                                                colSpan={colSpan}
                                                parentField={`${item.field}.`}
                                                formList={list}
                                            />
                                            <Button
                                                icon={<IconDelete />}
                                                shape='circle'
                                                status='danger'
                                                style={{
                                                    margin: '0 20px',
                                                }}
                                                onClick={() => remove(index)}
                                            ></Button>
                                            <Button
                                                shape='circle'
                                                onClick={() => move(index, index > 0 ? index - 1 : index + 1)}
                                            >
                                                {index > 0 ? <IconArrowRise /> : <IconArrowFall />}
                                            </Button>
                                        </Grid.Row>
                                    );
                                })}
                                <Space size={20}>
                                    <Button
                                        onClick={() => {
                                            add();
                                        }}
                                    >
                                        新增
                                    </Button>
                                </Space>
                            </div>
                        );
                    }}
                </Form.List>
            )
            // list 按照表格形式展示
            if (typeof show == 'function') {
                return (
                    <Form.Item
                        key={field}
                        {...formItemProps}
                        shouldUpdate={formItemProps.shouldUpdate || true}
                    >
                        {() => {
                            const values = form.getFields();
                            if (show(values)) {
                                return formListRender
                            }
                            return null;
                        }}
                    </Form.Item>
                )
            }
            return (
                <Form.Item
                    key={field}
                    {...formItemProps}
                >
                    {formListRender}
                </Form.Item>
            )
        }


        if (children) {
            const formObjectRender = notCol? (
                <Grid.Row>
                    <FormGenerate 
                        notCol={notCol}
                        colSpan={colSpan}
                        parentField={`${field}.`}
                        formList={children}
                    />
                </Grid.Row>
            ):(
                <FormGenerate 
                    notCol={notCol}
                    colSpan={colSpan}
                    parentField={`${field}.`}
                    formList={children}
                />
            )
            // 对象类型，使用model 弹窗编辑
            if (typeof show == 'function') {
                return (
                    <Form.Item
                        key={field}
                        {...formItemProps}
                        shouldUpdate={formItemProps.shouldUpdate || true}
                    >
                        {() => {
                            const values = form.getFields();
                            if (show(values)) {
                                return formObjectRender
                            }
                            return null;
                        }}
                    </Form.Item>
                )
            }
            return (
                <Form.Item
                    key={field}
                    {...formItemProps}
                >
                    {formObjectRender}
                </Form.Item>
            )
        }

        if(notCol){
            return (
                <FormItemRender
                    key={field}
                    render={o.render}
                    valueType={o.valueType}
                    fieldProps={o.fieldProps}
                    show={o.show}
                    field={field}
                    formItemProps={o.formItemProps}
                />
            )
        }

        return (
            <Grid.Col span={colSpan} {...colProps} key={field}>
                <FormItemRender 
                    render={o.render}
                    valueType={o.valueType}
                    fieldProps={o.fieldProps}
                    show={o.show}
                    field={field}
                    formItemProps={o.formItemProps}
                />
            </Grid.Col>
        )
    })

    return (
        <React.Fragment>
            {children}
        </React.Fragment>
    )
}


export default FormGenerate;