import lazyload, { loadCSS } from "./utils/lazyload";
import i18next from 'i18next';
import './style/global.less';
import React, { lazy, Suspense, useEffect, useMemo, useState } from 'react';
import ReactDOM from 'react-dom';
import { HashRouter, Redirect, Route, Switch, Router, useHistory } from "react-router-dom";
import { history } from '@/utils/history';
import { initIframe } from "./iframe";
import { initIframeApp } from './iframeApp';
import { useObserver } from "mobx-react-lite";


i18next.init({
    // 其他配置选项...

    returnNull: false,  // 设置为 true 时，未匹配到时返回 null
    returnEmptyString: false,  // 设置为 true 时，未匹配到时返回空字符串

    // 其他配置选项...
});

const win = window as any;
const Main = () => {


    return useObserver(() => {
    
    
        return (
            <Router history={history}>
                <Switch>
                    {/* 应用首页 */}
                    <Route exact path="/codes/*" component={lazyload(() => import('./index'))} />
                    {/* 应用开发 */}
                    <Route exact path="/app/:id/*" component={lazyload(() => import('./layout/AppLayout'))} />
                    {/* 应用平台（具体页面）开发 */}
                    <Route exact path="/dev/:id/*" component={lazyload(() => import('./layout/DevLayout'))} />
                    <Route exact path="/dev-develop/:id" component={lazyload(() => import('./pages/preview/dev'))} />
                    <Route exact path="/dev-preview/:id" component={lazyload(() => import('./pages/dev/preview'))} />
                    {/* 插件开发和预览 */}
                    <Route exact path="/plugin-view/:id/*" component={lazyload(() => import('./pages/preview/plugin'))} />
                    <Route exact path="/plugin-v/:id/:version/*" component={lazyload(() => import('./pages/preview/plugin'))} />
                    <Route exact path="/plugin/:id/*" component={lazyload(() => import('./layout/PluginLayout'))} />
                    {/** 项目开发和预览 */}
                    <Route exact path="/project-view/:id/*" component={lazyload(() => import('./pages/preview/project'))} />
                    <Route exact path="/project-v/:id/:version/*" component={lazyload(() => import('./pages/preview/project'))} />
                    <Route exact path="/project/:id/*" component={lazyload(() => import('./layout/ProjectLayout'))} />
                    {/* 应用预览 */}
                    <Route exact path="/preview/:id/*" component={lazyload(() => import('./pages/preview/web'))} />
                    {/* 应用版本预览 */}
                    <Route exact path="/v/:id/:version/*" component={lazyload(() => import('./pages/preview/v'))} />
                    {/** 发布应用（已弃用） */}
                    {/* <Route exact path="/run/*" component={lazyload(() => import('./environments/run'))} /> */}
                    {/** 当前应用预览 */}
                    <Route exact path="/view/:id/*" component={lazyload(() => import('./pages/view'))} />
                    <Route path="/">
                        <Redirect to={`/codes/`} />
                    </Route>
                </Switch>
            </Router>
        )

    })
}

if(win.iframeApp){
    initIframeApp();
}else if(win.iframePage){
    initIframe();
}else {
    ReactDOM.render(<Main />, document.getElementById('root'));
}
