/**
 * @name 返回多级别数据
 */
export function convertToTree(data, key: string = 'id', parentKey: string = 'parentId'): any[] {
  const map = {}; // 使用普通对象代替 Map
  const roots = [];

  // 将每个节点存储到 map 中
  for (let i = 0; i < data.length; i++) {
    const { [key]: id } = data[i];
    const children = [];
    map[id] = { ...data[i], children }; // 将节点存储到 map 中
  }

  // 遍历数据，构建树形结构
  for (let i = 0; i < data.length; i++) {
    const { [key]: id, [parentKey]: uid } = data[i];
    const parent = map[uid]; // 获取父节点对象
    if (parent) {
      parent.children.push(map[id]); // 将节点添加到父节点的 children 数组中
    } else {
      roots.push(map[id]); // 没有父节点，将节点添加到根节点数组中
    }
  }

  return roots; // 返回根节点数组
}

/*
* @name 解析JSONSchema数据 (将JSONSchema转为JSON数据)
* @param json  JSONSchema
* @param data  // jsonSchema 路径变量会根据data值进行替换
*/
export const schemaToJSON = (json: JSONSchema, data?: any, option:{
  // 是否返回空值，undefined值 （默认不返回）
  isNull?: boolean;
 } = {}) => {
  if(!json) return json;
  // 新加逻辑，json允许直接输入字符串（此处逻辑，目前用于flow流程节点中，body 参数
  if(typeof json === 'string') return json;
  const value = json.default;
  let val: any = value;
  switch (json.type) {
    case 'string':
      val = value;
      break;
    case 'object':
      const properties = json.properties;
      if (properties) {
        val = {};
        Object.keys(properties).forEach((key) => {
          // 5.6，判断对象是否不存在，undefined （不在返回到json中）
          const objVal = schemaToJSON(properties[key], data);
          if(objVal !== undefined || option.isNull){
            val[key] = objVal;
          }
        });
      }
      break;
    case 'array':
      if(value && Array.isArray(value)){
        val = value
      }else if(json.items){
        if(Array.isArray(json.items)){
          val = json.items.map((o) => schemaToJSON(o, data));
        }else {
          // Array<object> 类型，未指定默认值，返回空数组
          val = [];
          // const item = schemaToJSON(json.items as JSONSchema, data);
          // val = item? [item] : [];
        }
      }
      break;
    case 'integer':
    case 'number':
      val = value;
      break;
    case 'null':
      val = null;
    break;
  }
  return val;
};

/**
 *  根据JSONSchema 生成表格列表数据（Table）
 * @param o JSONSchema
 * @param path string
 */
export const schemaToList = (o: JSONSchema, path = ['$'], {
  key = path[0],
  schemaPath = path,
  parent = null
}: {
  key?: string,
  schemaPath?: string[],
  parent?: JSONSchema | null
} = {}) => {
  const params: JSONSchemaItemProps = {
    id: Math.random().toString(36).slice(2),
    type: o.type,
    path: path,
    schemaPath,
    key: key,
    // _parentStore: parent,
    _store: o,
  };
  switch (o.type) {
    case 'array':
      if (o.items) {
        if (!Array.isArray(o.items)) {
          if (o.items.type === 'object' && o.items.properties) {
            const properties: any = o.items.properties;
            const keys = Object.keys(properties);
            params.children = keys.map((key) => {
              return schemaToList(
                properties[key],
                [...path, '0', key],
                {
                  key,
                  parent: o,
                  schemaPath: [...schemaPath, 'items', 'properties', key],
                }
              );
            });
          } else {
            params.children = [
              schemaToList(
                o.items, 
                [...path, '0'],
              {
                key: '0',
                parent: o,
                schemaPath: [...schemaPath, 'items'],
              }),
            ];
          }
        } else {
          params.children = o.items.map((option, i) => {
            return schemaToList(
              option, 
              [...path, i.toString()],
              {
                key: `${i}`, 
                parent: o,
                schemaPath: [...schemaPath, 'items', i.toString()],
            });
          });
        }
      }
      break;
    case 'object':
      if (o.properties) {
        const properties: any = o.properties;
        const keys = Object.keys(properties);
        params.children = keys.map((key) => {
          return schemaToList(
            properties[key],
            [...path, key],
            {
              key,
              parent: o,
              schemaPath: [...schemaPath, 'properties', key]
          });
        });
      }
      break;
  }
  return params;
};


/**
 * 将JSONSchema 转为 Descriptions-data 列表
 * @param schema 
 * @returns 
 */
export const schemaToDescriptionsData = (schema: JSONSchema, data: Record<string, any> = {}) => {
    const { children: list = [] } = schemaToList(schema);
  
    return list.filter((o: any) => {
        const { show } = o._store;
        if(show && typeof show == 'function') return show(data);
        return true;
    }).map((o) => {
      const { _store, key } = o;
      const { title, type, enum: enumList, format, fieldProps, default: defaultValue, colProps = {} }: any = _store;
  
      const getValue = () => {
        if(format == "i18n" && fieldProps.value){
          return i18next.t(fieldProps.value, data);
        }
        if(enumList){
            const item = enumList.find((o) => o.value == data[key]);
            if(item) return item.label;
        }
        return data[key] || defaultValue;
      }
  
      return {
        key,
        label: title || key,
        value: getValue(),
        format: format,
        span: colProps.span,
      }
    })
}



/**
 * 将JSONSchema 转为 Columns对象
 * @param schema 
 * @returns 
 */
export const schemaToTableColumn = (schema: JSONSchema): ProColumn[] => {
  const list = schemaToList(schema).children || [];

  const recursionList = (arr: any[]): ProColumn[] => {
    if(!arr) return [];
    return  arr.map((o) => {
      const { _store, key } = o;
      const { title, type, enum: valueEnum, widget, columnProps, format, fieldProps } = _store;
      if(type == 'object') return null;
      const item: ProColumn = {
        title: title || key,
        // 默认对齐方式：数字默认靠右展示 其他靠左
        align: ['number', 'integer'].includes(type as string)? 'right' : 'left',
        dataIndex: key,
        widget,
        format,
        fieldProps,
        enum: valueEnum,
        ...columnProps
      }
      return item;
    }).filter((o) => o)
  }

  return recursionList(list);
}



/**
 * @name 根据table schema 生成适用查询的schema
 * @param schema 
 * @returns schema
 */
export const tableSchemaToSearchSchema = (schema: JSONSchemaCustom) => {
  if(!schema && !schema.properties) return schema;

  const objs: JSONSchemaCustom = { type: "object", properties: {} };
  const keys = Object.keys(schema.properties);
  for (const key of keys) {
    const item = schema.properties[key];
    const obj: JSONSchemaCustom = { ...item };
    const { format } = item;
    
    switch(format){
      case 'date':
        obj.type = "array";
        obj.format = "dateRange";
      break;
      case 'dateTime':
        obj.type = "array";
        obj.format = 'dateRange';
        obj.fieldProps = { ...item.fieldProps, showTime: true };
      break;
      case 'time':
        obj.type = "array";
        obj.format = 'timeRange';
        obj.fieldProps = { ...item.fieldProps, showTime: true };
      break;
      default: 
        if(item.type == 'array' && item.enum){
          let enumKeys = item.enum;
          if(typeof item.enum[0]  === 'object'){
            enumKeys = item.enum.map((o) => o.value);
          }
          obj.enum = enumKeys;
        }
    }

    objs.properties[key] = obj;
  }

  
  return objs;
}



const getOptions = (enumList: JSONSchema['enum']) => {
  return enumList.map((o) => {
    if(typeof o === 'object') return o;
    return { value: o, label: o }
  })
}

/**
 * @name 根据JSONSchema转换为form表单集合
 * @param schema
 * @param field 当前field 参数
 */
export const schemaToFormItem = (originSchema: JSONSchema, field: string = "formData"): FormItem[] => {
  const jsonSchema = _.cloneDeep(toJS(originSchema));
  const getFormItem = (schema: JSONSchema) => {
    if(!schema || !schema.type) return [];
    const properties = schema?.properties;
    const getSchemaItem = (option: JSONSchemaCustom, key): FormItem => {
      const { 
        type = 'string', title, format, pattern, 
        enum: enumList, description,
        extraInfo = {},
        colProps, show, anyOf,
        ...props
      } = option;
      const { jsDocs } = extraInfo;
      // 注释信息
      let extra = description;
      if(!extra && jsDocs){
        for (const item of jsDocs) {
          if(item.comment) extra = item.comment;
          if(item.tags && item.tags.zh) extra = item.tags.zh;
        }
      }
      const getShouldUpdate = (value: any) => {
        if(Array.isArray(value)){
          return (prev, record) => {
            return value.some((k) => prev[k] !== record[k]);
          }
        }else {
          if(typeof value === "object"){
            const keys = Object.keys(value);
            return (prev, record) => {
              return keys.some((k) => prev[k] !== record[k]);
            }
          }
          return value;
        }
      }
      
      let item: FormItem = {
        ...props,
        field: key,
        valueType: "input",
        formItemProps: {
          extra,
          label: title || key,
          rules: [],
          ...option.formItemProps,
          shouldUpdate: getShouldUpdate(option.formItemProps?.shouldUpdate)
        },
        show,
        colProps,
        fieldProps: { ...option.fieldProps },
      };
      const { label, rules } = item.formItemProps
      // 判断当前表单是否为必填
      if (schema.required && schema.required.includes(key)) {
        rules.push({ required: true, message: i18next.t('current.field.cannot.be.empty') })
      }
      if(pattern){
        rules.push({ match: new RegExp(pattern), message: i18next.t('current.field.format.validation.failed') })
      }

      if(format){
        // config.schema.formats[format]
        switch(format as string){
          case 'radio':
          case 'radioButton':
          case "select":
            if(enumList){
              item.fieldProps = {
                options: enumList.map((o) => {
                  if(typeof o === 'object') return o;
                  return { value: o, label: o }
                }),
                ...item.fieldProps
              } as any
            }
        }
        if(['phone', 'email'].includes(format)){
          // 这边代表正则类型
          rules.push({ match: new RegExp(Pattern[format]), message: i18next.t('current.field.format.validation.failed') })
        }else {
          item.valueType = format as any;
        }
        return item;
      }  else {
        // 判断类型，根据类型指定参数值
        switch (type) {
          case 'array':
            // item = _.assign(item, { valueType: 'EditorTable' }) as FormItem;
            if (option.items && !Array.isArray(option.items)) {
              item.list = getSchemaItem(option.items, key).children;
              return item;
            }else {
              // array 类型如果有 enumList 则使用多选
              if(enumList && Array.isArray(enumList)){
                item = _.assign(item, {
                  valueType: "select",
                  fieldProps: {
                    mode: "multiple",
                    options: getOptions(enumList),
                    ...item.fieldProps,
                  }
                } as unknown as FormItem);
                return item;
              }
              // item 不同规则数组忽略（未开发）
              return;
            }
            break;
          case 'object':
            item.children = getFormItem(option)
            if(!item.children.length) return;
            break;
          case 'string':
            if(format){
              // 定义了特殊类型，需要特别处理的特殊类型
              switch(format){
                case 'dateTime':
                  item =  _.assign(item, {
                    valueType: "date",
                    fieldProps: { showTime: true, ...option.fieldProps }
                  } as unknown as FormItem);
                break;
                // email, ip, url
                case 'email':
                case 'ip':
                case 'url':
                  rules.push({
                    type: format,
                    validateLevel: 'warning',
                  })
                break;
              }
            }
            break;
          case 'integer':
            item = _.assign(item, { valueType: 'inputNumber' }) as FormItem;
            item.fieldProps = { precision: 0, ...item.fieldProps };
            break;
          case 'number':
            item = _.assign(item, { valueType: 'inputNumber' });
            break;
          case 'boolean':
            item = _.assign(item, { valueType: 'switch' });
            break;
        }
      }
      if(enumList && Array.isArray(enumList)){
        item = _.assign(item, {
          valueType: 'select',
          fieldProps: {
            options: getOptions(enumList),
            ...item.fieldProps,
          }
        } as unknown as FormItem);
      }
    
      return item;
    }
    if (!properties || typeof properties !== 'object') {
      return schema.type == "object"? [] : [getSchemaItem(schema, field)];
    }
    const keys = Object.keys(properties);

    return keys.map((key) => {
      return getSchemaItem(properties[key], key);
    }).filter((item, i) => {
      return item;
    });
  }


  return getFormItem(jsonSchema);

};
