import React, { useContext, useEffect } from 'react';
import {
  Tooltip,
  Input,
  Avatar,
  Select,
  Dropdown,
  Menu,
  Divider,
  Message,
  Button,
} from '@arco-design/web-react';
import {
  IconLanguage,
  IconNotification,
  IconSunFill,
  IconMoonFill,
  IconUser,
  IconSettings,
  IconPoweroff,
} from '@arco-design/web-react/icon';
import IconButton from './IconButton';
import language from '../../../locales/index';
import styles from './style/index.module.less';
import { observer } from 'mobx-react-lite';
import user from '../../../store/user';
import theme from '../../../store/theme';
import i18next from 'i18next';
import utils from "utils"
import { useHistory } from 'react-router-dom';
import config from 'config';

const { t } = i18next;

function Navbar({ show }: { show: boolean }) {
  const history = useHistory();

  const { lang, changeLang } = language;

  function logout() {
    // setUserStatus('logout');
    // window.location.href = '/login';
    user.logout();
    utils.history.push('/login');
  }

  function onMenuItemClick(key) {
        switch(key){
          case "logout":
            logout();
          break;
          case "user":
            history.push(config.admin_path + '/user/profile')
          break;
      }
  }
  
  const userInfo = user.info;

  if (!show) {
    return null;
  }


  const droplist = (
    <Menu onClickMenuItem={onMenuItemClick}>
      <Menu.Item key="user">
          <IconUser className={styles['dropdown-icon']} />
          {t('user.info')}
      </Menu.Item>
      <Divider style={{ margin: '4px 0' }} />
      <Menu.Item key="logout">
        <IconPoweroff className={styles['dropdown-icon']} />
        {t('logout.exit')}
      </Menu.Item>
    </Menu>
  );

  

  return (
    <div className={styles.navbar}>
      <div className={styles.left}>
        <div className={styles.logo}>
          {config.web_logo? <img className="h-4" src={config.web_logo} /> : undefined}
          <div>
            {t(config.web_name)}
          </div>
        </div>
      </div>
      <ul className={styles.right}>
        <li>
          <Input.Search
            className={styles.round}
            placeholder={t('input.content.query')}
          />
        </li>
        <li>
          <Select
            triggerElement={<IconButton icon={<IconLanguage />} />}
            options={language.options}
            value={lang}
            triggerProps={{
              autoAlignPopupWidth: false,
              autoAlignPopupMinWidth: true,
              position: 'br',
            }}
            trigger="hover"
            onChange={(value) => {
              changeLang(value);
              Message.info(`${t('language.switch')}${value}`);
            }}
          />
        </li>
        {/* <li>
          <MessageBox>
            <IconButton icon={<IconNotification />} />
          </MessageBox>
        </li> */}
        <li>
          <Tooltip
            content={
              theme.theme === 'light'
                ? t('toggle.dark.mode')
                : t('toggle.light.mode')
            }
          >
            <IconButton
              icon={theme.theme == 'light' ? <IconMoonFill /> : <IconSunFill />}
              onClick={() => theme.setTheme(theme.theme == 'light' ? 'dark' : 'light')}
            />
          </Tooltip>
        </li>
        {/* <Settings /> */}
        {userInfo && (
          <li>
            <Dropdown droplist={droplist} position="br" trigger="click">
              <Avatar size={32} style={{ cursor: 'pointer' }}>
                {userInfo.avatar? <img alt="avatar" src={userInfo.avatar} /> :  userInfo.login_name}
              </Avatar>
            </Dropdown>
          </li>
        )}
      </ul>
    </div>
  );
}

export default observer(Navbar);
