import app from "@/store/app";
import { PluginInfo, pluginExtrainfoDefaultValue } from "@/types/plugin";
import ajax from "@/utils/ajax";
import _ from "lodash";
import { action, observable, makeObservable, computed, toJS } from "mobx";
import React, { useMemo } from "react";

class Store {
    @observable list: PluginInfo[] = [];
    isReady = false;


    getStore = () => {
        return { 
            isReady: this.isReady,
            list: toJS(this.list),
        }
    }

    @action setStore = (data: ReturnType<typeof this.getStore>) => {
        _.assign(this, data);
    }

    @action
    setList = (data) => {
        this.list = data;
    }

    @computed get pluginsList () {
        // 过滤所有存在的插件
        return this.list.filter((o) => {
            return app.extraInfo.plugins[o.pluginId];
        })
    }


    init = async () => {
        if(this.isReady) return;
        await this.getPlugins();
        this.isReady = true;
    }

    getPlugins = () => {
        return ajax.post('/apijson/get', {
            [`PluginProject[]`]: {
                "join": "&/Plugins",
                'PluginProject': {
                    projectId: app.info.projectId,
                },
                "Plugins": {
                    "isActive": 1,
                    "@order": "sort+",
                    "id@": "/PluginProject/pluginId",
                    "@column": "name,description,author,releaseVersion,extraInfo"
                },
                "PluginVersion[]": {
                    count: 0,
                    PluginVersion: {
                        "isReleased": 1,
                        "pluginId@": "PluginProject[]/PluginProject/pluginId",
                        "@column": "versionNumber,pluginId,description",
                        "@order": "versionNumber-"
                    }
                }
            }
        }).then((res) => {
            this.setList(res.PluginProject.map((o) => {
                return {
                    ...o,
                    extraInfo: o.extraInfo? JSON.parse(o.extraInfo) : pluginExtrainfoDefaultValue,
                    PluginVersion: o.PluginVersion.map((o) => {
                        return {
                            ...o,
                            value: o.versionNumber,
                            label: o.versionNumber
                        }
                    })
                }
            }));
            return this.list;
        })
    }

    constructor() {
        makeObservable(this);
    }
}

export default new Store();