import React from "react";
import { FormItem } from "../../interface";
import { Input, InputTag, DatePicker, TimePicker, InputNumber, Select, Radio, Switch } from "@arco-design/web-react";
import Selector from "@system/Selector";
import TreeSelector from "@system/TreeSelector";
import i18next from "i18next";
import UploadImg from "@system/UploadImg";
import { EditorQuill } from "@system/Quill";
import { EditMarkdown } from "@system/Markdown";


interface FieldProps {
  fieldProps: Record<string, any>
  valueType: FormItem['valueType']
  disabled?: boolean;
  onChange?: any;
  value?: any;
}

const Field = ({
  fieldProps,
  disabled,
  valueType = 'input',
  ...props
}: FieldProps) => {

  const onChange = async (val: any, ...arr: any[]) => {
    let value = val;
    // props.onChange 来源 Form.Item
    if (props.onChange) props.onChange(value);
    // 此处onChange事件，来源组件Props
    if (fieldProps.onChange) fieldProps.onChange(value);
  };

  const fieldParams = { disabled, ...fieldProps, value: props.value, onChange }


  switch (valueType) {
    case "selector":
      return (
        <Selector
          {...fieldParams}
        />
      )
    case "treeSelector":
      return (
        <TreeSelector {...fieldParams} />
      )
    case "input":
      return (
        <Input
          placeholder={i18next.t('please.enter')}
          autoComplete="off"
          {...fieldParams}
        />
      );
    case "inputTag":
      return (
        <InputTag  
          placeholder={i18next.t('please.enter')}
          {...fieldParams}
        />
      )
    break;
    case 'text':
      return (
        <Input.TextArea 
          placeholder={i18next.t('please.enter')}
          autoComplete="off"
          {...fieldParams}
        />
      )
    case "password":
      return (
        <Input.Password 
          placeholder={i18next.t('please.enter')}
          autoComplete="off"
          {...fieldParams}
        />
      )
    case "date": 
      return (
        <DatePicker
          placeholder={i18next.t('please.select')}
          {...fieldParams}
        />
      );
    case "dateTime":
      return (
        <DatePicker
          placeholder={i18next.t('please.enter')}
          {...fieldParams}
        />
      )
    case "dateRange":
      return (
        <DatePicker.RangePicker
          placeholder={[i18next.t('start.date'), i18next.t('end.date')]}
          {...fieldParams}
        />
      )
    case "time": 
      return (
        <TimePicker
          placeholder={i18next.t('please.enter')}
          {...fieldParams}
        />
      );
    case "timeRange":
      return (
        <TimePicker.RangePicker 
          {...fieldParams}
        />
      )
    case "inputNumber":
      return (
        <InputNumber
          placeholder={i18next.t('please.enter')}
          {...fieldParams}
        />
      );
    case "select":
      // console.log('formFields.select', fieldProps, props)
      return (
        <Select
          placeholder={i18next.t('please.enter')}
          allowClear
          {...fieldParams}
        />
      );
    case "radio":
      return (
        <Radio.Group
          {...fieldParams}
        >
        </Radio.Group>
      )
    case "radioButton":
      return (
        <Radio.Group
          type="button"
          {...fieldParams}
        >
        </Radio.Group>
      )
    case "switch":
      return (
        <Switch
          checked={props.value}
          {...fieldParams}
        />
      );
    case "image":
      return (
        <UploadImg
          {...fieldParams}
        />
      )
    case "richText":
      return (
        <EditorQuill 
          {...fieldParams}
        />
      )
    case 'editMarkdown':
      return (
        <EditMarkdown 
          {...fieldParams}
        />
      )
    default:
      return null;
  }

};


export default Field