import React from 'react';
import loadable from '@loadable/component';
// import Spin from '@arco-design/web-react/lib/Spin';
import styles from '../style/main.module.less';
import { loadComponentKey } from '@/types/lazy';

// https://github.com/gregberge/loadable-components/pull/226
export function load(fn, options) {
  const Component = loadable(fn, options);

  Component.preload = fn.requireAsync || fn;

  return Component;
}

function LoadingComponent(props: {
  loader: any;
  error: boolean;
  timedOut: boolean;
  pastDelay: boolean;
}) {
  if (props.error) {
    console.error(props.error);
    return null;
  }
  return (
    <div className={styles.spin}>
      <div id="loader" className={styles.loader}>
        <div className={styles.dot}></div>
        <div className={styles.dot}></div>
        <div className={styles.dot}></div>
      </div>
    </div>
  );
}

const lazyload = (loader) => {
  if(!loader) return () => null;
  return  load(loader, {
      fallback: LoadingComponent({
        loader,
        pastDelay: true,
        error: false,
        timedOut: false,
      }),
  });
}

export default lazyload;


const scriptCache = {};

/**
 * @name 动态加载js
 * @param url 
 * @returns 
 */
export function loadScript(url) {
  return new Promise((resolve, reject) => {
    if (scriptCache[url]) {
      // 如果 URL 已经加载过，直接返回缓存的 Promise 对象
      resolve(true);
      return;
    }

    const script = document.createElement('script');
    script.src = url;
    script.onload = () => {
      scriptCache[url] = true; // 将 URL 标记为已加载
      resolve(true);
    };
    script.onerror = reject;
    document.head.appendChild(script);
  });
}

/**
 * 动态加载CSS
 */
export function loadCSS(url) {
  var link = document.createElement('link');
  link.rel = 'stylesheet';
  link.type = 'text/css';
  link.href = url;
  document.head.appendChild(link);
}



export const componentCache: Partial<Record<loadComponentKey, any>> = {
  
};



/**
 * 下载文件
 */
export function dwonloadFile(content: string, filename: string) {
  // 创建隐藏的可下载链接
  const eleLink = document.createElement('a');
  eleLink.download = filename;
  eleLink.style.display = 'none';
  // 字符内容转变成blob地址
  const blob = new Blob([content]);
  eleLink.href = URL.createObjectURL(blob);
  // 触发点击
  document.body.appendChild(eleLink);
  eleLink.click();
  // 然后移除
  document.body.removeChild(eleLink);
}