/**
 * @name 异步更新函数（防止重复触发）
 */
export const asyncAwaitFunction = (fun: (...arg) => Promise<any>) => {
  let loading = false;
  return (...arg) => {
    if(loading) return;
    return fun(...arg).finally(() => {
      loading = false;
    })
  }
}

/**
 * @name 延迟更新函数
 * @param num 延迟更新时间
 * @param fun 延迟num（ms）后调用
 */
export const delayedFunction = (fun: (...arg) => void, time: number = 300) => {
  let timer = null;
  return (...arg) => {
    if(timer){
      clearTimeout(timer);
    }
    timer = setTimeout(() => fun(...arg), time)
  }
}

/**
 * @name 层级数据扁平化处理
 * @param tree 
 * @returns 
 */
export function flattenTree(tree: any[]) {
  const result = [];
  
  function flatten(node) {
    result.push(node);
    
    if (node.children && node.children.length > 0) {
      node.children.forEach(flatten);
    }
  }
  
  tree.forEach(flatten);
  
  return result;
}



/**
 * @name 返回多级别数据
 */
export function convertToTree(data, key: string = 'id', parentKey: string = 'parentId'): any[] {
  const map = {}; // 使用普通对象代替 Map
  const roots = [];

  // 将每个节点存储到 map 中
  for (let i = 0; i < data.length; i++) {
    const { [key]: id } = data[i];
    const children = [];
    map[id] = { ...data[i], children }; // 将节点存储到 map 中
  }

  // 遍历数据，构建树形结构
  for (let i = 0; i < data.length; i++) {
    const { [key]: id, [parentKey]: uid } = data[i];
    const parent = map[uid]; // 获取父节点对象
    if (parent) {
      parent.children.push(map[id]); // 将节点添加到父节点的 children 数组中
    } else {
      roots.push(map[id]); // 没有父节点，将节点添加到根节点数组中
    }
  }

  return roots; // 返回根节点数组
}


/**
 * 对多层级数据返回map 数据
 */
export function treeMap(data: any[], fun:(item: any) => any){
  const loop = (list) => {
    return list.map((o) => {
        // 写入到mianRoutes
        return {
          ...fun(o),
          children: (o.children && o.children.length)? loop(o.children) : undefined,
        }
    })
  }
  return loop(data)
}

/**
 * @name 搜索多级列表节点
 */
export function searchTreeNode(data, value: string, key: string = "id"): any {
  let result = null;
  const loop = (list) => {
    for (const item of list) {
      if(item[key] === value) {
        result = item;
        break;
      }
      if(item.children) loop(item.children);
    }
  }
  loop(data)

  return result;
}

/**
 * @name 深层遍历返回指定keys或自定义返回参数
 */
export function getSpecificValues(list: any[], funkeys: string[] | ((item: any, parentItem) => any)) {

  const recursionList = (list, parentItem = null) => {
    const resultList: any = [];
    for (const data of list) {
      let result: any = {};
      if(typeof funkeys === "function"){
        result = funkeys(data, parentItem);
      }else {
        funkeys.forEach(key => {
          if (data[key]) {
            result[key] = data[key];
          }
        });
      }
    
      if (Array.isArray(data.children) && data.children.length > 0) {
        result.children = recursionList(data.children, result);
      }
      resultList.push(result);
    }
    return resultList;
  }

  return recursionList(list);
}


/**
 * @name 多级数据扁平化处理
 * @param data 多级数据
 */
export function treeToFlatten(data, key: string = 'id', parentKey: string = 'parentId') {
  let flatData = [];
  if(!Array.isArray(data)) return [];

  data.forEach(item => {
    const id = item[key] || getUuid();
    flatData.push({ ...item, [key]: id, children: undefined });

    if (item.children) {
      const childrenData = treeToFlatten(
        item.children.map((o) => ({ ...o, [parentKey]: id })), 
        key, 
        parentKey
      );
      flatData = flatData.concat(childrenData);
    }
  });

  return flatData;
}



/**
 * @name 扁平化多级节点删除
 * @param data 要删除的列表数据
 * @param nodeId 要删除的id
 * 
 */
export function deleteNode(
  data, 
  nodeId: string,
  key: string = 'id', 
  parentKey: string = 'parentId'
) {
  // 创建一个包含每个节点的子节点的空数组的对象
  const childMap = {};
  const nodeMap = {};
  for (const node of data) {
    if (node[key] !== nodeId) {
      const parentId = node[parentKey];
      if (parentId !== 0) {
        if (!childMap[parentId]) {
          childMap[parentId] = [];
        }
        childMap[parentId].push(node[key]);
      }
    }
  }

  // 递归遍历树并删除节点
  function deleteNodeRecursively(nodeId) {
    nodeMap[nodeId] = true;
    if (childMap[nodeId]) {
      for (const childId of childMap[nodeId]) {
        deleteNodeRecursively(childId);
      }
      delete childMap[nodeId];
    }
  }

  // 调用递归函数并返回处理后的扁平数据集
  deleteNodeRecursively(nodeId);
  return data.filter(node => node[key] !== nodeId && !nodeMap[node[key]]);
}


/**
 * 
 * @param data 递级列表
 * @param searchQuery 搜索命令
 * @returns 
 */
export function filterTreeData(data: any[], searchQuery: (item) => boolean){
  return data.map(node => {
    if (searchQuery(node)) {
      return node;
    } else if (node.children) {
      const filteredChildren = filterTreeData(node.children, searchQuery);
      if (filteredChildren.length > 0) {
        return {
          ...node,
          children: filteredChildren,
          toggled: true,
        };
      }
    }
    return null;
  }).filter(node => node !== null);
}


// 获取置顶 url 参数
export const getQueryParam = (path: string, key: string): string  => {
  if (!key || !path) return '';
  const array = path.substring(path.indexOf('?') + 1).split(/[&=]/);
  const index = array.indexOf(key);
  if (index !== -1 && index % 2 === 0) {
      return decodeURIComponent(array[index + 1]);
  } else {
      return '';
  }
}

// 获取url所有参数
export const getAllQueryParam = (path: string): Record<string, string> => {
  const result = Object.create(null);
  if (!path || path.indexOf('?') === -1) return result;
  path = path.substring(path.indexOf('?') + 1);
  const array = path.split(/[&=]/);
  for (let i = 0; i < array.length; i += 2) {
      result[array[i]] = decodeURIComponent(array[i + 1]);
  }
  return result;
}

// 将对象转换为url参数
export const queryStringify = (obj: Record<string, any>): string => {
  return Object.keys(obj).map(key => `${key}=${obj[key]}`).join('&');
}


/**
 * @name 获取一个指定范围的数字
 */
export const generateRandomNumber = (min: number, max: number = Date.now()): number => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

/**
 * 根据 Object 生成options 数组
 */
export const enumToOptions = (enums: Record<string, any>) => {
  return Object.keys(enums).map((k) => ({ label: enums[k], value: k }))
}




/**
 * 将数组转换为JSONSchema
 */
export function paramListToJSONSchema(list: any[]): JSONSchema {
  if(!Array.isArray(list)) return undefined;
  const result = list.filter((o) => !o.name);
  return {
    type: 'object',
    properties: {
      ...result.reduce(
        (obj, item) =>
          _.assign(obj, {
            [item.name]: {
              type: "object",
              description: item.description || item.label || '',
            } as JSONSchema,
          }),
        {}
      ),
    },
  };
}



/**
 * @name 根据数据返回新的内容
 * @param jsonSchema schema { type: 'object', properties: { a: { type: "object" , properties: { b: 111 } }}}
 * @param fieldPath 路径信息 a.b
 * @returns SchemaJSON
 */
export function getFieldSchema(jsonSchema: JSONSchema, fieldPath: string | string[]) {
  // 将字段路径拆分为数组
  let pathSegments = fieldPath;
  if(typeof pathSegments === 'string'){
    pathSegments = pathSegments.split(/\.|\[|\]\.?/).filter(segment => segment !== "");
  }

  // 逐级查找对应字段的描述信息
  let currentSchema = jsonSchema;
  for (const segment of pathSegments) {
    if (currentSchema && currentSchema.properties && currentSchema.properties[segment]) {
      currentSchema = currentSchema.properties[segment];
    } else if (currentSchema && currentSchema.items) {
      if (Array.isArray(currentSchema.items)) {
        // 处理 items 是数组的情况
        const arrayIndex = parseInt(segment, 10);
        if (!isNaN(arrayIndex) && currentSchema.items[arrayIndex]) {
          currentSchema = currentSchema.items[arrayIndex];
        } else {
          // 如果索引无效或找不到对应的字段描述信息，返回 null
          currentSchema = null;
          break;
        }
      } else if (currentSchema.items.properties && currentSchema.items.properties[segment]) {
        // 处理 items 是对象的情况
        currentSchema = currentSchema.items.properties[segment];
      } else {
        // 处理 items 是基本类型的情况
        currentSchema = currentSchema.items;
      }
    } else {
      // 如果找不到对应的字段描述信息，返回 null
      currentSchema = null;
      break;
    }
  }

  // console.log('getFieldSchema', jsonSchema, fieldPath, currentSchema);

  // 返回对应字段的描述信息
  return currentSchema;
}


/**
 * @name 根据table schema 生成适用查询的schema
 * @param schema 
 * @returns schema
 */
export const tableSchemaToSearchSchema = (schema: JSONSchema) => {
  if(!schema && !schema.properties) return schema;

  const objs: JSONSchema = { type: "object", properties: {} };
  const keys = Object.keys(schema.properties);
  for (const key of keys) {
    const item = schema.properties[key];
    const obj: JSONSchema = { ...item };
    const { format } = item;
    
    switch(format){
      case 'date':
        obj.type = "array";
        obj.format = "dateRange";
      break;
      case 'dateTime':
        obj.type = "array";
        obj.format = 'dateRange';
        obj.fieldProps = { ...item.fieldProps, showTime: true };
      break;
      case 'time':
        obj.type = "array";
        obj.format = 'timeRange';
        obj.fieldProps = { ...item.fieldProps, showTime: true };
      break;
      default: 
        if(item.type == 'array' && item.enum){
          let enumKeys = item.enum;
          if(typeof item.enum[0]  === 'object'){
            enumKeys = item.enum.map((o) => o.value);
          }
          obj.enum = enumKeys;
        }
    }

    objs.properties[key] = obj;
  }

  
  return objs;
}




// 添加全局样式
export function addCSS(cssText: string, id?: string) {
  let style: HTMLStyleElement = id? document.getElementById(id) : null as any;
  if (!style) {
      style = document.createElement('style');
      style.type = 'text/css';
      style.setAttribute('id', id);
      // style.innerHTML = cssText;
      // 替换图片地址
      style.innerHTML = file.toImagePath(cssText);
      document.head.appendChild(style);
  }
  style.innerHTML = cssText;
}

// 移除全局样式
export function removeCss(id: string){
  const style = document.getElementById(id);
  if(style){
    document.head.removeChild(style);
  }
}

/**
 * 字段转换
 * @param n_ID
 * @returns nId
 */
export function convertToCamelCase(key: string) {
  // 将字符串全部转为小写
  const lowercaseStr = key.toLowerCase();

  // 根据下划线拆分字符串，然后将每个部分的首字母大写
  const parts = lowercaseStr.split('_');
  const camelCaseStr = parts[0] + parts.slice(1).map(word => word.charAt(0).toUpperCase() + word.slice(1)).join('');

  return camelCaseStr;
}


/**
 * 加载Script
 * @param url 
 * @returns 
 */
export const loadScript = (url: string) => {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = url;
    script.setAttribute("type", "module")
    script.onload = (res) => {
      console.log('loadScript', res, url)
      resolve(true);
    };
    script.onerror = reject;
    document.head.appendChild(script);
  });
}



