import { Button, Grid, Message, Modal, Slider, Upload, UploadProps } from '@arco-design/web-react';
import { useObserver } from 'mobx-react-lite';
import { ReactNode, useCallback, useEffect, useMemo, useState } from 'react';
import Store from './store';
import user from '../../../store/user';
import './index.less';
import config from 'config';
import { Cropper } from "./Cropper";


/**
 * 方便用户图片上传，主要改动点
 * @tip1 自定义 value 接管了 list ( 为了 form 表单接管状态方便 )
 * @tip2 默认value 是string 类型，如果想要上传多个图片 可以使用 multipleChoice
 */
export interface UploaderProps extends Omit<UploadProps, 'onChange'> {
  value?: string | string[];
  store?: Store;
  // 是否开启多选
  multipleChoice?: boolean;
  // 是否裁剪图片
  cropped?: boolean;
  children?: ReactNode;
  onChange?: (value: string | string[], list: any | any[]) => void;
}







const UploadImg = ({ value, onChange, multipleChoice, store:uStore, cropped, ...props }: UploaderProps) => {

  const [store] = useState(() => uStore || new Store())
  return useObserver(() => {

    const values = useMemo(() => {
      if(!value) return [];
      const values = Array.isArray(value)? value : [value];
      return values;
    },[value])

    useEffect(() => {
      if(!values.length) {
        store.setList([]);
      };
      const map = new Map(store.list.filter((o) => o.url).map((o) => [o.url, o]));
      const list = values.filter((url) => !map.has(url));
      if(list.length){
        store.setList(store.list.concat(list.map((url) => {
          return {
            uid: Math.random().toString(32).slice(2),
            url: url,
            status: 'done'
          }
        })))
      }
    },[values])


    const beforeUpload = useMemo(() => {
      
      return (file) => {

        // if(!store.isAcceptFile(file, 'image/*')){
        //   Message.info('不接受的文件类型，请重新上传指定文件类型~');
        //   return Promise.reject("文件类型错误")
        // }

        if(!cropped) return Promise.resolve();
        return new Promise((resolve) => {
          const url = URL.createObjectURL(file);
          const modal = Modal.confirm({
              title: '裁剪图片',
              onCancel: () => {
                Message.info('取消上传');
                resolve(false);
                modal.close();
              },
              simple: false,
              content: (
                <Cropper
                  url={url}
                  file={file}
                  onOk={(file) => {
                    resolve(file);
                    modal.close();
                  }}
                  onCancel={() => {
                    resolve(false);
                    Message.info('取消上传');
                    modal.close();
                  }}
                />
              ),
              footer: null,
          });
        });
      }
    },[cropped])

    return (
        <Upload
          imagePreview
          name="image"
          limit={multipleChoice? 9 : 1}
          action={`${config.api_path}/upload-img`}
          headers={{
            Authorization: `Bearer ${user.info.accessToken}`
          }}
          beforeUpload={beforeUpload}
          listType='picture-card'
          accept='image/*'
          onDrop={(e) => {
              let uploadFile = e.dataTransfer.files[0]
              if (store.isAcceptFile(uploadFile, 'image/*')) {
                  return
              } else {
                  Message.info('不接受的文件类型，请重新上传指定文件类型~');
              }
          }}
          {...props}
          fileList={store.list}
          onChange={(list) => {
            store.setList(list)
            if(onChange && JSON.stringify(store.value) !== JSON.stringify(values)){
              // 文件列表变更
              if(multipleChoice){
                // 多选
                onChange(store.value, store.list);
              }else {
                onChange(store.value[0], store.list[0]);
              }
            }
          }}
        />
    );
  })
};
  
export default UploadImg;