import _ from 'lodash';
import { modulePlatform } from "@/types/module";
import { Message } from "@arco-design/web-react";
import { action, computed, observable, makeObservable, toJS } from 'mobx';
import ajax from '@/utils/ajax';
import userStore from './userStore';
import { AppExtraInfo, AppInfo, AppPluginItem } from '@/types/app';
import { delayedFunction } from '@/utils';
import theme from './theme';
import { PluginInfo } from '@/types/plugin';
import file from './file';
import { ProjectExtraInfo } from '@/types/project';
import language from './language';



// if(config.ENV === "local"){
//     setInterval(() => {
//         ajax.get('/user/getUserData');
//     },1000 * 120)
// }

const langKey = "wizui-lang";
/**
 * 全局页面数据
 */
class App {
    verison: string;
    // 系统应用id
    appId: string = 'page';
    // 当前承租人
    tenantId: string = '';
    // 应用所属平台 
    platform: modulePlatform = modulePlatform.pc;
    // 当前登陆人用户id
    userId?: string = "";
    // 当前多语言
    @observable lang = localStorage.getItem(langKey) || "zh-CN";

    @observable info: AppInfo = {};
    @observable extraInfo: AppExtraInfo = {
        plugins: {},
        themes: {},
        customVariable: { type: "object" },
        configuration: {},
        languageKeys: ['zh-CN', 'en-US', 'zh-HK']
    };
    @observable projectInfo: ProjectExtraInfo = {
        customVariables: []
    }

    getStore = () => {
        return {
            ..._.pick(this, ['verison', 'appId', 'tenantId', 'platform', 'userId', 'lang']),
            info: toJS(this.info),
            extraInfo: toJS(this.extraInfo),
            projectInfo: toJS(this.projectInfo),
        }
    }

    @action setStore = (data) => {
        console.log('data', data)
        Object.assign(this, data);
    }


    @action setLang = (key) => {
        localStorage.setItem(langKey, key);
        this.lang = key;
    }

    // 当前平台主题
    get theme() { return theme.theme }

    // 切换当前主题
    setTheme = theme.setTheme;

    constructor(){
        makeObservable(this);
    }

    delayedExtraInfo = delayedFunction(() => {
        this.savaExtraInfo();
    },1000)
    /**
     * @保存插件
     */
    savaExtraInfo = () => {
        return ajax.post('/apijson/put', {
            Application: {
                id: this.info.id,
                extraInfo: this.extraInfo,
            }
        })
    }

    @action assignExtraInfo = (data: Partial<AppExtraInfo>) => {
        this.extraInfo = { ...this.extraInfo, ...data };
    }
    delPlugin = (id: string) => {
        // 删除插件
        this.assignExtraInfo({
            plugins: {
                ...this.extraInfo.plugins,
                [id]: undefined
            }
        })
    }
    addPlugin = (plugin: PluginInfo) => {
        this.assignExtraInfo({
            plugins: {
                ...this.extraInfo.plugins,
                [plugin.pluginId]: {
                    isActive: true,
                    id: plugin.pluginId,
                    version: "",
                }
            }
        })
    }
    getPlugin = (id: string) => {
        if(this.extraInfo.plugins[id]) return this.extraInfo.plugins[id];
        return { isActive: false, id } as AppPluginItem;
    }
    // 插曲插件集合列表
    @computed get plugins(){
        const list = Object.values(this.extraInfo.plugins).filter((o) => o.isActive);
        return list;
    }
    // 更新插件信息
    @action updatePlugin = (id: string, plugin: AppPluginItem) => {
        this.assignExtraInfo({
            plugins: {
                ...this.extraInfo.plugins,
                [id]: _.assign({ id }, this.getPlugin(id), plugin),
            }
        })
    }

    @action setInfo = (data) => {
        this.info = data;
        this.assignExtraInfo(data.extraInfo);
        this.projectInfo = { customVariables: [], ...data.projectInfo };
        // 设置当前App 主题色
        theme.setAppTheme(this.extraInfo.themes);
        this.tenantId = this.info.tenant;
    }


    // 获取所有配置合并后的json
    @computed get allVariablesSchema(): JSONSchema{
        let projects = {};
        for (const item of this.projectInfo.customVariables) {
            projects = { ...projects, ...item.properties };
        }

        return {
            type: "object",
            properties: {
                ...projects,
                ...this.extraInfo.customVariable.properties,
            },
        }
    }


    // 获取应用信息，
    getAppInfo = (id: string) => {
        this.appId = id;
        return ajax.post('/dev/getAppInfo', {
            appId: id
        }).then(async (res) => {
            if(!res.info){
                Message.success("应用不存在，或没有权限");
                throw `${id} 应用获取失败`
            }
            userStore.setDevToken(res.token);
            const { info } = res;
            if(info.extraInfo) info.extraInfo = info.extraInfo? JSON.parse(info.extraInfo) : {};
            if(info.projectInfo) info.projectInfo = info.projectInfo? JSON.parse(info.projectInfo) : {};
            this.setInfo(info);
            return Promise.all([
                file.getList(), // 加载文件信息
                language.reloadApp([]),
            ])
        })
    }


    /**
     * 获取应用插件列表
     */
    getPluginList = async (): Promise<PluginInfo[]> => {
        const { plugins = {} } = this.info.extraInfo || {}
        const pluginList = Object.values(plugins).filter((o) => o.isActive);
        const pluginIds = pluginList.map((o) => o.id);
        if(!pluginIds.length) return [];
        return ajax.post('/apijson/get', {
            "Plugins[]": {
                "Plugins": {
                    "id{}": pluginIds,
                    "@column": ['id', 'name', 'author', 'platform', 'isActive', 'description', 'updatedAt', 'releaseVersion'].join(',')
                }
            }
        }).then((res) => {
            return res.Plugins as PluginInfo[]
        })
    }
    
}

export default new App();